import re

_ZONE_BY_PREFIX = {"AB": 2, "CD": 3, "EF": 4}

def _resolve_zone(normalized: str) -> int:
    """Apply route rules to a normalized postcode."""
    if not re.fullmatch(r"[A-Z]{2}-\d{4}", normalized):
        return 0
    return _ZONE_BY_PREFIX.get(normalized[:2], 5)

def zone_for_postcode(postcode: str) -> int:
    """Return a zone for any postcode string, ignoring case and edge spaces."""
    return _resolve_zone(postcode.strip().upper())

