package mail;

import java.util.List;

/** Utilities for formatting mail recipients for display and delivery headers. */
public final class Recipients {
    /**
     * Joins non-null recipient names in input order with comma-space.
     * An empty list maps to the empty string; each name is preserved as given.
     * @param names non-null names in display order.
     * @return names joined with comma-space, or empty string for an empty list.
     */
    public static String join(List<String> names) {
        StringBuilder joined = new StringBuilder();
        boolean first = true;
        for (String name : names) {
            if (!first) joined.append(", ");
            joined.append(name);
            first = false;
        }
        return joined.toString();
    }

    public static void main(String[] args) {
        List<String> names = List.of("Mira Chen", "Ari Patel", "Nia Brooks");
        System.out.println(join(names));
    }
}
